// Mobile page staff open from Telegram / email. Viewing never claims:
// link scanners (Outlook Safe Links, chat previews) only do GETs, while
// claiming is a POST from a real button tap.
const r = $json.res || {};
const esc = (s) => String(s === null || s === undefined ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const css = `:root{--bg:#F3F5F1;--surface:#fff;--ink:#12241F;--muted:#5B6B65;--rule:#DAE0DA;--accent:#0B6E4F;--late:#C4363D;color-scheme:light;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}
@media (prefers-color-scheme:dark){:root{--bg:#0D1613;--surface:#14201C;--ink:#E6EEEA;--muted:#9AAAA4;--rule:#26342F;--accent:#3FBF8F;--late:#FF6B70;color-scheme:dark}}
*,*::before,*::after{box-sizing:inherit}body{margin:0;background:var(--bg);color:var(--ink);font-family:"Readex Pro","Segoe UI","Noto Sans Arabic",Tahoma,system-ui,sans-serif;font-weight:300;line-height:1.5}
.wrap{max-width:560px;margin:0 auto;padding:22px 18px 40px}.school{color:var(--muted);font-size:14px}
h1{font-weight:400;font-size:30px;line-height:1.2;margin:10px 0 6px}.meta{color:var(--muted);margin:0 0 18px}
.status{border-left:3px solid var(--accent);padding:10px 14px;background:var(--surface);margin:0 0 18px;border-radius:0 8px 8px 0}
.status.late{border-color:var(--late)}.actions{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:0 0 12px}
.btn{display:block;text-align:center;text-decoration:none;padding:14px 12px;border-radius:10px;border:1px solid var(--rule);background:var(--surface);color:var(--ink);font:inherit;font-weight:500;width:100%;cursor:pointer}
.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}.btn.wide{grid-column:1/-1}
form{margin:0 0 10px}dl{display:grid;grid-template-columns:auto 1fr;gap:6px 16px;margin:22px 0;font-size:15px}
dt{color:var(--muted)}dd{margin:0;overflow-wrap:anywhere}h2{font-size:16px;font-weight:500;margin:26px 0 8px}
ul{padding-left:18px;margin:0;color:var(--muted);font-size:14px}.foot{color:var(--muted);font-size:13px;margin-top:28px}
a:focus-visible,.btn:focus-visible{outline:2px solid var(--accent);outline-offset:3px}`;
const page = (title, body) => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><meta name="robots" content="noindex"><title>${esc(title)}</title><link href="https://fonts.googleapis.com/css2?family=Readex+Pro:wght@300;400;500&display=swap" rel="stylesheet"><style>${css}</style></head><body><main class="wrap">${body}</main></body></html>`;

if (!r.found) {
  return [{ json: { status_code: 404, html: page('Link not valid', `<h1>This link is not valid</h1><p class="meta">It may be incomplete or copied without the end. Open the lead again from the original message.</p>`) } }];
}
const inq = r.inquiry || {};
const L = inq.lead || {};
const tz = r.timezone || 'Asia/Dubai';
const me = r.agent;
const fmt = (iso) => iso ? new Intl.DateTimeFormat('en-GB', { timeZone: tz, weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }).format(new Date(iso)) : '';
const mins = (a, b) => Math.max(0, Math.round((new Date(b) - new Date(a)) / 60000));
const dur = (m) => m < 60 ? `${m} min` : `${Math.floor(m / 60)} h ${m % 60} min`;
const channel = inq.channel === 'meta' ? (inq.platform === 'ig' ? 'Instagram lead form' : 'Facebook lead form') : ({ web: 'Website form', whatsapp: 'WhatsApp' }[inq.channel] || inq.channel);
const langName = { ar: 'Arabic', en: 'English', fr: 'French', ur: 'Urdu', hi: 'Hindi' }[inq.language] || inq.language || '';

let status;
let late = false;
if (inq.contacted_at) {
  status = `Contacted ${fmt(inq.contacted_at)}, ${dur(mins(inq.received_at, inq.contacted_at))} after the inquiry arrived.`;
} else if (inq.claimed_at) {
  const who = inq.claimed_by ? inq.claimed_by.name : 'Someone';
  const mine = me && inq.claimed_by && inq.claimed_by.id === me.id;
  status = (r.result === 'claimed' && mine ? 'You claimed this inquiry. Reminders have stopped.' : `${mine ? 'You' : esc(who)} claimed this ${fmt(inq.claimed_at)}.`)
    + ` Response time ${dur(mins(inq.received_at, inq.claimed_at))}.`;
} else {
  const open = mins(inq.received_at, new Date().toISOString());
  late = inq.sla_due_at && new Date(inq.sla_due_at) < new Date();
  status = `Not claimed yet. Waiting ${dur(open)}${late ? ', past the promised response time' : ''}.`;
}

const digits = String(L.phone_e164 || '').replace(/\D/g, '');
const firstName = L.first_name || L.full_name || '';
const agentName = me ? me.name : 'the Admissions team';
const school = r.school_name || 'our school';
const greet = inq.language === 'ar'
  ? `مرحباً ${firstName}، معك ${agentName} من قسم القبول في ${school}. شكراً لتواصلكم معنا، متى يناسبكم أن نتحدث؟`
  : `Hello ${firstName}, this is ${agentName} from ${school} Admissions. Thank you for your inquiry. When would be a good time to talk?`;

let actions = '<div class="actions">';
if (digits) {
  actions += `<a class="btn" href="tel:+${digits}">Call</a>`;
  actions += `<a class="btn" href="https://wa.me/${digits}?text=${encodeURIComponent(greet)}">WhatsApp</a>`;
}
if (L.email) actions += `<a class="btn${digits ? ' wide' : ''}" href="mailto:${esc(L.email)}">Email</a>`;
actions += '</div>';
if (!inq.claimed_at) actions += `<form method="post"><input type="hidden" name="a" value="claim"><button class="btn primary" type="submit">Claim this inquiry</button></form>`;
if (!inq.contacted_at) actions += `<form method="post"><input type="hidden" name="a" value="contacted"><button class="btn" type="submit">Mark as contacted</button></form>`;

const rows = [
  ['Phone', L.phone_e164], ['Email', L.email], ['Language', langName], ['Channel', channel],
  ['Campaign', inq.campaign_name], ['Ad set', inq.adset_name], ['Ad', inq.ad_name], ['Form', inq.form_name],
  ...Object.entries(inq.answers || {}), ['Message', inq.message], ['Received', fmt(inq.received_at)],
  ['Assigned to', inq.assigned_agent && inq.assigned_agent.name],
].filter(([, v]) => v !== null && v !== undefined && v !== '');
const history = (inq.history || []).map((h) => `<li>${esc(fmt(h.received_at))}: ${esc(h.channel === 'meta' ? 'Meta form' : h.channel === 'web' ? 'Website' : h.channel)}${h.campaign_name ? ', ' + esc(h.campaign_name) : ''}</li>`).join('');

const body = `<div class="school">${esc(school)} · Admissions</div>
<h1 dir="auto">${esc(L.full_name || 'Unknown name')}</h1>
<p class="meta">${esc(channel)}${inq.campaign_name ? ' · ' + esc(inq.campaign_name) : ''}${inq.is_test ? ' · test inquiry' : ''}</p>
<div class="status${late ? ' late' : ''}">${status}</div>
${actions}
<dl>${rows.map(([k, v]) => `<dt>${esc(k)}</dt><dd dir="auto">${esc(v)}</dd>`).join('')}</dl>
${history ? `<h2>Earlier inquiries from this family</h2><ul>${history}</ul>` : ''}
<p class="foot">Reference LO-${esc(inq.inquiry_id)}${me ? ' · signed in as ' + esc(me.name) : ''}</p>`;
return [{ json: { status_code: 200, html: page(`${L.full_name || 'Lead'} · Admissions`, body) } }];
